#!/usr/bin/env python3
"""Apply the validated Unit07 retry patches plus a second narrow depth layer."""
from pathlib import Path
SOURCE=Path(__file__).with_name('recalibrate_final_arabic_c1_unit07.py')
RETRY=Path(__file__).with_name('recalibrate_final_arabic_c1_unit07_retry.py')
ns={'__file__':str(RETRY)}
prefix=RETRY.read_text(encoding='utf-8').split('for old,new in patches.items():',1)[0]
exec(prefix,ns)
text=SOURCE.read_text(encoding='utf-8')
for old,new in ns['patches'].items():
    assert text.count(old)==1, f'expected one first-layer insertion point: {old[:40]!r}'
    if old.endswith("''',"):
        new += "''',"
    text=text.replace(old,new)
extras={
"ساعد ذلك على جعل العودة المتغيرة دليلًا له قدرة تفسيرية وتنبؤية محدودة بدل أن تكون مجرد تشابه جميل يلاحظه الناقد بعد معرفة الخاتمة.":"ساعد ذلك على جعل العودة المتغيرة دليلًا له قدرة تفسيرية وتنبؤية محدودة بدل أن تكون مجرد تشابه جميل يلاحظه الناقد بعد معرفة الخاتمة. كما قارنت المجموعة ترتيب الجملتين داخل الفصلين وسألت هل المسافة بينهما تسمح للقارئ بتذكر العلاقة من دون شرح مباشر. وجدوا إشارات وسيطة إلى النافذة تجعل العودة قابلة للاستدعاء، فصار الارتباط جزءًا من تنظيم العمل عبر الزمن لا مجرد تكرار في طرفيه. وإذا حذفت تلك الإشارات في نسخة تجريبية، ضعفت قوة العلاقة وأصبح الاعتماد على ذاكرة القارئ أكبر.",
"سجلت المراجعة هذا الفرق صراحة، لأن مصدر الدليل يؤثر في نوع الادعاء الذي يستطيع الناقد الدفاع عنه.":"سجلت المراجعة هذا الفرق صراحة، لأن مصدر الدليل يؤثر في نوع الادعاء الذي يستطيع الناقد الدفاع عنه. ثم طلبت من المشاركين ترتيب القرائن من الأكثر مباشرة إلى الأكثر اعتمادًا على معرفة خارج العمل. اختلفوا في بعض المواضع لكنهم اتفقوا على أن خلل المرآة والضوء أقرب إلى المادة نفسها من قصة عن حياة الفنان. سمح هذا الترتيب للمراجعة بأن توضح لماذا يمكن لقراءة أن تكون ممكنة ثقافيًا ومع ذلك أضعف داخل حدود الصور المعروضة.",
"ومنعت الحجة من نسب كل أثر سمعي إلى البنية نفسها بلا تمييز.":"ومنعت الحجة من نسب كل أثر سمعي إلى البنية نفسها بلا تمييز. وفي نسخة أخرى قرأ المؤدي المقاطع بإيقاع شبه ثابت، فبقي الانقطاع في الموضع نفسه لكن أثره العاطفي انخفض. استعملت الناقدة الفرق لتفصل بين البنية التي تحدد موقع التحول والأداء الذي يغير شدته. بذلك أصبحت الحجة أقدر على تفسير لماذا يمكن لقراءتين صوتيتين أن تختلفا في الإحساس مع بقائهما متفقتين على موضع التحول الشكلي.",
"هكذا تدربوا على المعايرة بوصفها مهارة تحريرية يمكن فحصها، لا مجرد موقف عام من الحذر.":"هكذا تدربوا على المعايرة بوصفها مهارة تحريرية يمكن فحصها، لا مجرد موقف عام من الحذر. ثم طلب منهم المدرس أن يكتبوا أقوى اعتراض ممكن على الصيغة التي اختاروها. إذا كان الاعتراض يعتمد على تفصيل أهملوه، أضافوه إلى الحجة وخفضوا الثقة عند الحاجة. وإذا كان مجرد احتمال لا يملك سندًا، ذكروه من دون إعطائه الوزن نفسه. ساعد ذلك على الفصل بين الانفتاح على البدائل ومساواة كل احتمال لمجرد إمكان تصوره.",
"أظهر ذلك أن قارئين قد يصلان إلى نتائج مختلفة لأن أحدهما يمنح سياقًا خارجيًا وزنًا أكبر، لا لأن أحدهما رأى النص والآخر لم يره.":"أظهر ذلك أن قارئين قد يصلان إلى نتائج مختلفة لأن أحدهما يمنح سياقًا خارجيًا وزنًا أكبر، لا لأن أحدهما رأى النص والآخر لم يره. وفي آخر المقارنة كتب كل فريق ما الذي سيجعل خريطته أقوى وما الذي سيجعلها أضيق. لم يطلب أمين اتفاقًا نهائيًا، بل أراد أن يعرف هل يستطيع كل طرف تحديد اختبار أو تفصيل أو مصدر يمكنه تغيير الحكم. عندما أمكن ذلك صار الخلاف منتجًا، لأن القراءات لم تعد محصنة من المراجعة بمجرد وصفها بأنها شخصية.",
}
for old,new in extras.items():
    assert text.count(old)==1, f'expected one second-layer insertion point: {old[:40]!r}'
    text=text.replace(old,new)
exec(compile(text,str(SOURCE),'exec'),{'__name__':'__main__','__file__':str(SOURCE)})
